const replacements: Record<string, string> = { 'ß': 'ss', 'ẞ': 'ss', 'æ': 'ae', 'Æ': 'ae', 'œ': 'oe', 'Œ': 'oe', 'ø': 'o', 'Ø': 'o', 'ł': 'l', 'Ł': 'l', 'đ': 'd', 'Đ': 'd', 'ð': 'd', 'Ð': 'd', 'þ': 'th', 'Þ': 'th', 'ı': 'i', 'İ': 'i' };
const normalized = title
  .toLowerCase()
  .replace(/[ßẞæÆœŒøØłŁđĐðÐþÞıİ]/g, (letter) => replacements[letter] ?? letter)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/&/g, ' and ');
return normalized
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
